27	/**
28	 * 泄流指令链服务：下达（随方案）→签收→执行→回执。
29	 *
30	 * <p>签收时限：以指令签收截止时刻为准，当前时刻不早于截止时刻（恰满 15 分钟）仍未签收，
31	 * 签收动作自动登记升级值班领导；截止时刻前签收正常。</p>
32	 * <p>回执口径：实际总泄量与方案总泄量偏差比例恰等 10% 视为一致；超过 10% 必须附原因，
33	 * 否则拒绝回执。回执以 requestId 幂等，同键重放返回首次回执，异参 409。</p>
34	 */
35	@Service
36	public class OrderService {
37	
38	    /** 自动升级的值班领导（合成值班角色）。 */
39	    static final String DUTY_LEADER = "值班领导";
40	
41	    private final OrderRepository orderRepository;
42	    private final PlanRepository planRepository;
43	    private final IdempotentRepository idempotentRepository;
44	    private final JsonSupport jsonSupport;
45	    private final FloodControlProperties properties;
46	    private final Clock clock;
47	
48	    public OrderService(OrderRepository orderRepository, PlanRepository planRepository,
49	                        IdempotentRepository idempotentRepository, JsonSupport jsonSupport,
50	                        FloodControlProperties properties, Clock floodClock) {
51	        this.orderRepository = orderRepository;
52	        this.planRepository = planRepository;
53	        this.idempotentRepository = idempotentRepository;
54	        this.jsonSupport = jsonSupport;
55	        this.properties = properties;
56	        this.clock = floodClock;
57	    }
58	
59	    /**
60	     * 签收指令；恰满签收时限未签收则自动升级值班领导（升级留痕，签收仍可补登）。
61	     */
62	    @Transactional
63	    public OrderView sign(String orderNo, OrderActionRequest request) {
64	        OrderPO order = requireOrder(orderNo);
65	        LocalDateTime now = LocalDateTime.now(clock);
66	        if (order.status.equals(OrderStatus.SIGNED.name())
67	                || order.status.equals(OrderStatus.EXECUTING.name())
68	                || order.status.equals(OrderStatus.RECEIPTED.name())) {
69	            throw FloodControlException.business("ORDER_ALREADY_SIGNED",
70	                    "指令 " + orderNo + " 已签收，当前状态 " + order.status);
71	        }
72	        boolean timedOut = !now.isBefore(order.signDeadline);
73	        if (OrderStatus.ESCALATED.name().equals(order.status)) {
74	            // 已被超时巡检升级：仅允许补签收一次（升级态保留）
75	            if (order.signedAt != null) {
76	                throw FloodControlException.business("ORDER_ALREADY_SIGNED",
77	                        "指令 " + orderNo + " 已补签收，当前状态 " + order.status);
78	            }
79	            int signed = orderRepository.signKeepEscalated(order.id, request.operator(), now);
80	            if (signed == 0) {
81	                throw FloodControlException.business("ORDER_SIGN_FAILED",
82	                        "指令 " + orderNo + " 升级后补签收失败");
83	            }
84	            order.signedAt = now;
85	            order.signer = request.operator();
86	            orderRepository.addEvent(order.id, "SIGNED", now,
87	                    request.operator() + " 在升级值班领导后补签收");
88	        } else if (timedOut) {
89	            // 恰满时限（当前时刻不早于截止时刻）：先自动升级值班领导，再登记补签收（保留升级态）
90	            int escalated = orderRepository.escalate(order.id, DUTY_LEADER, now);
91	            if (escalated == 0) {
92	                throw FloodControlException.business("ORDER_SIGN_FAILED",
93	                        "指令 " + orderNo + " 当前状态不可签收: " + order.status);
94	            }
95	            int signed = orderRepository.signKeepEscalated(order.id, request.operator(), now);
96	            if (signed == 0) {
97	                throw FloodControlException.business("ORDER_SIGN_FAILED",
98	                        "指令 " + orderNo + " 升级后补签收失败: " + order.status);
99	            }
100	            order.status = OrderStatus.ESCALATED.name();
101	            order.escalatedAt = now;
102	            order.escalatedTo = DUTY_LEADER;
103	            order.signedAt = now;
104	            order.signer = request.operator();
105	            orderRepository.addEvent(order.id, "ESCALATED", now,
106	                    "恰满签收时限 " + properties.getSignTimeoutMinutes()
107	                            + " 分钟未签收，自动升级值班领导，后由 " + request.operator() + " 补签收");
108	        } else {
109	            int rows = orderRepository.sign(order.id, request.operator(), now);
110	            if (rows == 0) {
111	                throw FloodControlException.business("ORDER_SIGN_FAILED",
112	                        "指令 " + orderNo + " 当前状态不可签收: " + order.status);
113	            }
114	            order.signedAt = now;
115	            order.signer = request.operator();
116	            order.status = OrderStatus.SIGNED.name();
117	            orderRepository.addEvent(order.id, "SIGNED", now,
118	                    request.operator() + " 在签收时限内签收");
119	        }
120	        return toView(order);
121	    }
