126	     */
127	    @Transactional
128	    public boolean escalateIfTimeout(String orderNo) {
129	        OrderPO order = requireOrder(orderNo);
130	        LocalDateTime now = LocalDateTime.now(clock);
131	        if (!OrderStatus.ISSUED.name().equals(order.status)) {
132	            return false;
133	        }
134	        if (now.isBefore(order.signDeadline)) {
