18	import java.util.Map;
19	import org.springframework.stereotype.Service;
20	import org.springframework.transaction.annotation.Transactional;
21	
22	/**
23	 * 降雨预警/险情处置链服务；以 requestId 幂等，同键同参返回首次结果，同键异参 409。
24	 */
25	@Service
26	public class WarningService {
27	
28	    private final WarningRepository warningRepository;
29	    private final PondRepository pondRepository;
30	    private final IdempotentRepository idempotentRepository;
31	    private final BusinessNoGenerator noGenerator;
32	    private final JsonSupport jsonSupport;
33	    private final Clock clock;
34	
35	    public WarningService(WarningRepository warningRepository, PondRepository pondRepository,
36	                          IdempotentRepository idempotentRepository,
37	                          BusinessNoGenerator noGenerator, JsonSupport jsonSupport,
38	                          Clock floodClock) {
39	        this.warningRepository = warningRepository;
40	        this.pondRepository = pondRepository;
41	        this.idempotentRepository = idempotentRepository;
42	        this.noGenerator = noGenerator;
43	        this.jsonSupport = jsonSupport;
44	        this.clock = floodClock;
45	    }
46	
47	    /**
48	     * 创建处置链（降雨预警/险情报送共用同一处置链入口）。
49	     */
50	    @Transactional
51	    public WarningView open(WarningRequest request) {
52	        PondPO pond = pondRepository.requireByCode(request.pondCode());
53	        String fingerprint = jsonSupport.fingerprint(fingerprintFields(request));
54	        LocalDateTime now = LocalDateTime.now(clock);
55	
56	        IdempotencyOutcome outcome = idempotentRepository.register(
57	                request.requestId(), "WARNING", fingerprint, now);
58	        if (!outcome.created()) {
59	            if (outcome.fingerprintMismatch()) {
60	                throw FloodControlException.conflict(
61	                        "requestId=" + request.requestId() + " 已用于不同参数的预警，请更换 requestId");
62	            }
63	            WarningPO existing = warningRepository.findByRequestId(request.requestId());
64	            return toView(existing, true);
65	        }
66	
67	        WarningPO po = new WarningPO();
68	        po.warningNo = noGenerator.next("YW");
69	        po.pondId = pond.id;
70	        po.title = request.title();
71	        po.rainSummary = request.rainSummary();
72	        po.status = ChainStatus.ACTIVE.name();
73	        po.requestId = request.requestId();
74	        po.openedAt = now;
75	        warningRepository.insert(po);
76	        WarningPO saved = warningRepository.findByRequestId(request.requestId());
77	        idempotentRepository.bindRef(request.requestId(), saved.id);
78	        return toView(saved, false);
79	    }
80	
81	    /**
82	     * 按编号查询；不存在抛 404。
83	     */
84	    public WarningPO requireByNo(String warningNo) {
85	        WarningPO warning = warningRepository.findByNo(warningNo);
86	        if (warning == null) {
87	            throw FloodControlException.notFound("处置链不存在: " + warningNo);
88	        }
89	        return warning;
90	    }
