55	     * 生成幂等指纹：将所有业务字段（含 requestId）放入有序 Map 后规范化序列化再 SHA-256。
56	     */
57	    public String fingerprint(Map<String, ?> fields) {
58	        TreeMap<String, Object> sorted = new TreeMap<>();
59	        sorted.putAll(fields);
60	        String canonical = toJson(sorted);
61	        try {
62	            MessageDigest digest = MessageDigest.getInstance("SHA-256");
63	            byte[] hash = digest.digest(canonical.getBytes(StandardCharsets.UTF_8));
64	            StringBuilder hex = new StringBuilder();
65	            for (byte b : hash) {
66	                hex.append(String.format("%02x", b));
67	            }
68	            return hex.toString();
69	        } catch (NoSuchAlgorithmException e) {
70	            throw new IllegalStateException("SHA-256 不可用", e);
71	        }
72	    }
73	}
