COMMENT ON TABLE order_event IS '指令链状态事件流（下达/签收/升级/执行/回执），可复算';

CREATE TABLE IF NOT EXISTS review_record (
    id BIGINT AUTO_INCREMENT PRIMARY KEY,
    warning_id BIGINT NOT NULL,
    plan_id BIGINT,
    order_id BIGINT,
    note VARCHAR(1024),
    created_at TIMESTAMP NOT NULL
