COMMENT ON TABLE idempotent_request IS '幂等记录：指纹覆盖 requestId 与全部业务字段，同键异参冲突';
COMMENT ON COLUMN idempotent_request.fingerprint IS 'SHA-256 指纹（含 requestId 及全部业务字段的规范化 JSON）';

