package com.example.starter.flood.web.dto;

import jakarta.validation.constraints.DecimalMin;
import jakarta.validation.constraints.NotNull;
import jakarta.validation.constraints.PositiveOrZero;
import java.math.BigDecimal;

/**
 * 入库洪水过程线点：相对上一演算版本时刻的分钟偏移与入库流量。
 *
 * @param minute 分钟偏移（首点必须为 0，严格递增）
 * @param inflowRate 入库流量，立方米每秒
 */
public record InflowPoint(
        @NotNull @PositiveOrZero Integer minute,
        @NotNull @DecimalMin("0.0") BigDecimal inflowRate) {
}

package com.example.starter.flood.web.dto;

import jakarta.validation.Valid;
import jakarta.validation.constraints.DecimalMin;
import jakarta.validation.constraints.NotBlank;
import jakarta.validation.constraints.NotEmpty;
import java.math.BigDecimal;
import java.util.List;

/**
 * 滚动演算请求：按入库洪水过程线重算调洪结果，恰满滚动周期触发；
 * 全部业务字段进入幂等指纹，源输入快照随版本保留可复算。
 *
 * @param requestId 幂等键
 * @param warningNo 关联处置链预警编号
 * @param hydrograph 入库洪水过程线（首点 minute=0，分钟严格递增）
 * @param dryBeachLength 当前干滩长度，米，可空（空值沿用上一版本）
 * @param phreaticDepth 当前浸润线埋深，米，可空（空值沿用上一版本）
 */
public record RollingRoutingRequest(
        @NotBlank String requestId,
        @NotBlank String warningNo,
        @NotEmpty @Valid List<InflowPoint> hydrograph,
        @DecimalMin("0.0") BigDecimal dryBeachLength,
        @DecimalMin("0.0") BigDecimal phreaticDepth) {
}

package com.example.starter.flood.web.dto;

import java.math.BigDecimal;
import java.time.LocalDateTime;

/**
 * 演算版本视图：任一历史版本可查，输入快照保留可单独复算。
 */
public record RoutingVersionView(
        String routingNo,
        String warningNo,
        Integer version,
        String triggerType,
        String prevRoutingNo,
        BigDecimal currentWaterLevel,
        BigDecimal currentStorage,
        BigDecimal availableCapacity,
        BigDecimal designFloodVolume,
        String capacityJudgment,
        String dangerJudgment,
        String inflowHydrograph,
        String inputSnapshot,
        String criterion,
