            // 同 requestId 重放已在下方幂等分支处理；此处为异键重复确认
            Map<String, Object> existing = idempotentRepository.findByRequestId(request.requestId());
            if (existing != null) {
                String fingerprint = jsonSupport.fingerprint(
                        fingerprintFields(adviceNo, request));
                if (fingerprint.equals(existing.get("fingerprint"))) {
                    return toView(advice, true);
