                planRepository.findById(advice.newPlanId) == null ? null : oldPlanId(advice));
        if ("ACCEPT_NEW_VERSION".equals(request.decision())) {
            // 按新版本方案下达新指令（钉住新版本号）；在途旧指令继续有效至回执
