            orderRepository.addEvent(order.id, "ISSUED", now,
                    "人工确认替代建议 " + adviceNo + "，按新方案版本 " + newPlan.planNo
                            + "（版本 " + newPlan.version + "）下达，确认人 " + request.operator());
